// Attack phase
level = min(1.0, stageTime / attack);

// Decay phase
decayAmount = (1.0 - sustain) * (stageTime / decay);
level = 1.0 - min(decayAmount, 1.0 - sustain);

// Sustain phase
level = sustain;

// Release phase
level = max(0.0, releaseStartLevel * (1.0 - stageTime / release));

// Find a free voice or take the next one in turn
voice = findFreeVoice();
if (voice == null) {
    voice = voices[nextVoiceIndex];
    nextVoiceIndex = (nextVoiceIndex + 1) % 8;
}
voice.noteOn(midiNote, velocity, sampleRate);
